const el=(tag,text)=>{const node=document.createElement(tag);if(text)node.textContent=text;return node;};
const money=value=>(value/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'});
export async function renderFreight(container,api){
 container.append(el('h2','Fragt og tilbud'),el('p','Kontrollér den konkrete kurv og adresse i PF Store eller med PF. Registrér PF’s pris ekskl. moms. Ingen ordre eller mail oprettes her.'));
 try{const data=await(await api('/api/admin/freight-quotes')).json();container.append(el('p','Smerchs tillæg pr. ordre: '+money(data.markupExVat)+' ekskl. moms. Tillægget styres centralt i SMERCH_FREIGHT_MARKUP_EX_VAT_DKK.'));
 for(const record of data.requests){const details=el('details'),summary=el('summary',[record.shipping.name,record.shipping.company,record.status==='accepted'?'Accepteret':record.quote?'Pris klar':'Afventer PF-pris',new Date(record.createdAt).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})].filter(Boolean).join(' · '));details.className='freight-request';details.open=record.status==='review';details.append(summary);const content=el('div');content.append(el('p',[record.shipping.street,record.shipping.postalCode+' '+record.shipping.city,record.shipping.country,record.shipping.deliveryComment].filter(Boolean).join(' · ')),el('p',record.shipping.email+' · '+record.shipping.phone),el('p','Standardlevering · Varepris inkl. moms: '+money(record.goodsTotalIncVat)));
 for(const line of record.lines){content.append(el('p',line.quantity+' × '+line.productId+' · '+line.sku+(line.decorations?.length?' · med tryk':' · uden tryk')));for(const decoration of line.decorations||[])content.append(el('p',[decoration.optionId,decoration.width+' × '+decoration.height+' mm',decoration.colors+' farver'].join(' · ')));}
 if(record.quote)content.append(el('p','PF-fragt: '+money(record.quote.supplierExVat)+' ekskl. moms · tillæg: '+money(record.quote.markupExVat)+' · kundens fragt inkl. moms: '+money(record.quote.customerIncVat)),el('p','Tilbuddet gælder til '+new Date(record.quote.validUntil).toLocaleString('da-DK',{timeZone:'Europe/Copenhagen'})));
 if(record.checkoutId){content.append(el('p','Accepteret på ordre '+record.checkoutId));details.append(content);container.append(details);continue;}
 const form=el('form'),groupInputs=[];
 for(const group of record.groups){const label=el('label','PF-fragt fra '+group.location+' · DKK ekskl. moms'),cost=el('input'),refLabel=el('label','PF-prisreference (hvis PF har angivet én)'),reference=el('input');cost.type='number';cost.min='0';cost.step='.01';cost.required=true;cost.value='';reference.maxLength=200;label.append(cost);refLabel.append(reference);form.append(label,refLabel);groupInputs.push({group,cost,reference});}
 const evidenceLabel=el('label','Hvor og hvornår er PF-prisen kontrolleret?'),evidence=el('textarea'),expiryLabel=el('label','Smerchs tilbud gælder til'),expiry=el('input');evidence.required=true;evidence.maxLength=1000;expiry.type='datetime-local';expiry.required=true;evidenceLabel.append(evidence);expiryLabel.append(expiry);form.append(evidenceLabel,expiryLabel);
 function check(text){const label=el('label',text),input=el('input');input.type='checkbox';label.prepend(input);form.append(label);return input;}
 const net=check('PF-prisen er i DKK ekskl. moms.'),complete=check('PF-prisen omfatter alle varer, pakker og planlagte leverancer i denne forespørgsel.'),free=check('PF har udtrykkeligt bekræftet 0 kr. i fragt (kun hvis relevant).');net.required=complete.required=true;
 const save=el('button',record.quote?'Erstat fragttilbud':'Gør fragtpris klar til kunden'),feedback=el('p');feedback.setAttribute('role','status');save.type='submit';form.append(save,feedback);form.onsubmit=async event=>{event.preventDefault();save.disabled=true;try{const groups=groupInputs.map(({group,cost,reference})=>{if(!/^\d+(\.\d{1,2})?$/.test(cost.value))throw Error('Angiv hver PF-pris med højst to decimaler.');return {location:group.location,supplierExVat:Math.round(Number(cost.value)*100),pfPriceReference:reference.value};});await api('/api/admin/freight-quotes/'+record.id,'POST',{groups,currency:'DKK',exVatConfirmed:net.checked,completeShipmentConfirmed:complete.checked,freeFreightConfirmed:free.checked,evidence:evidence.value,validUntil:new Date(expiry.value).toISOString()});feedback.textContent='Fragttilbuddet er klar på kundens betalingsside. Kunden skal godkende prisen før bestilling. Ingen mail er sendt.';}catch(error){feedback.textContent=error.message;}finally{save.disabled=false;}};content.append(form);details.append(content);container.append(details);
 }
 if(!data.requests.length)container.append(el('p','Ingen fragtforespørgsler endnu.'));
 }catch(error){container.append(el('p',error.message));}
}
